const r = $json;
const sum = (bucket) => Object.entries(r.totals?.[bucket] ?? {})
  .map(([currency, amount]) => `${amount} ${currency}`).join(', ');
return {
  json: {
    'Report ID': r.id,
    'Title': r.title,
    'Employee': r.employee?.name ?? '',
    'Order': r.orderCode ?? '',
    'Period': [r.dateFrom, r.dateTo].filter(Boolean).join(' – '),
    'Company paid': sum('companyPaid'),
    'To reimburse': sum('reimburse'),
    'Payroll deduction': sum('payroll'),
    'Submitted at': r.submittedAt,
  },
};
